{
 "research_concepts": [
  "Play-type effectiveness",
  "Points Per Possession (PPP)",
  "Opponent possession outcomes",
  "Sequential play analysis",
  "Lag effects",
  "AVOID labels",
  "Data quality of derived labels"
 ],
 "methodological_questions": [
  "Measuring subsequent opponent efficiency",
  "Attributing outcomes to preceding plays",
  "Handling time-series or sequential data in basketball",
  "Evaluating the drivers of derived labels",
  "Controlling for confounding factors in play-level analysis"
 ],
 "historical_evidence": [
  {
   "id": "FAM:SF-APPS-075",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Play types and players have a real downstream (opponent next-PPP) component beyond direct PPP. 4/8 PTs downstream real: CUT Ext 1.658 (supp +0.0220), TRANSITION 1.509 (+0.0145), SPOT_UP 1.303 (+0.0124), POST_UP 1.127 (+0.0194). DRIVE downstream not real (opp ATT +0.0024). Downstream effects are small (~0.01-0.02 PPP) relative to direct PPP gaps."
  },
  {
   "id": "FAM:SF-CHT-029",
   "status_as_recorded": "artifact",
   "finding": "Play-type actions have decaying cross-possession memory (lag-1 effect >= lag-2; not just score margin or team quality). FAIL decay-sanity: DRIVE lifts +0.015,+0.020,+0.018,+0.021,+0.020 (flat). Within-team: DRIVE lag-1 +0.015 to -0.002. Team-quality confound."
  },
  {
   "id": "FAM:SF-PAP-096",
   "status_as_recorded": "artifact",
   "finding": "Play-type classifier assisted-flag leak (SPOT_UP 100% makes). SPOT_UP 2.83 PPP (100% makes) and TRANSITION 0.62 PPP because assisted flag exists only on makes; after rewrite SPOT_UP ~1.16, TRANSITION ~1.20."
  },
  {
   "id": "FAM:SF-APPM-014",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Play-type label accuracy / distribution audit overall FAIL: OTHER 20.2% vs <10% target; 40.8% low confidence; DRIVE foul-draw 1.7% vs 14-22% benchmark; most PTs PPP above benchmark band; MIA identity checks fail."
  },
  {
   "id": "FAM:SF-CHT-025",
   "status_as_recorded": "artifact",
   "finding": "Play-type labeling audit: OTHER/DRIVE foul leakage. OTHER: 36% end in fouls, PPP inflated (FOUL_BUCKET). DRIVE: 12pp below foul benchmark (FOUL_LEAK). PNR shows 22% foul rate. Only 335 of 50,668 possessions (0.7%) map to a real play type via initiation_type."
  },
  {
   "id": "FAM:SF-APPA-030",
   "status_as_recorded": "inconclusive",
   "finding": "Play-type label backfill verification. PNR 28.7% FAIL (band 20-28%); PULL_UP 7.9% FAIL; 3100 games with team PNR >33% FAIL; 2024-25 PULL_UP ~0-1% for many teams. Final: FAIL."
  },
  {
   "id": "FAM:SF-APPA-005",
   "status_as_recorded": "untestable",
   "finding": "Defensive scheme change within game and across games (inferred labels). Inferred label cannot separate real defensive adjustment from offense executing differently; near-uniform transition matrices consistent with label noise."
  },
  {
   "id": "FAM:SF-APPS-058",
   "status_as_recorded": "untestable",
   "finding": "Observed on-ball defensive scheme labels (ORL-DET G1). Confident label rates 14.9% and 3.3%; NBA matchups feed did not populate switches_on."
  },
  {
   "id": "FAM:SF-APPA-050",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Superstar sequential suppression: opponent play before the star. PUTBACK is top suppressor for 6+ stars (e.g. D. Mitchell 1.178 to 0.884, d=-0.294, n_after=95; B. Beal d=-0.345 n=32; C. Holmgren d=-0.222 n=52). No multiplicity correction; n_after is 32-95 for several PUTBACK cells vs thousands of baseline possessions."
  },
  {
   "id": "FAM:SF09",
   "status_as_recorded": "inconclusive",
   "finding": "Double-suppression stacking (POST_UP then PUTBACK). Stacked delta -0.071 vs additive prediction -0.232 (less t). Baseline 1.210 n=960,764. After PUTBACK only 1.097 d=-0.113 n=15,898. After POST_UP only 1.091 d=-0.119 n=76,329. Stacked 1.138 d=-0.071 n=1,047 vs additive prediction -0.232. Mitchell after PUTBACK 0.919 vs 1."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-PAP-096",
   "what_failed": "Measuring play-type PPP using early versions of the play-type inferrer.",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw) due to assisted flag existing only on makes, inflating SPOT_UP PPP and deflating TRANSITION PPP."
  },
  {
   "id": "FAM:SF-APPM-014",
   "what_failed": "Assuming inferred play-type labels match benchmark volumes, foul rates, PPP and known team identities.",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw); LIM:label_or_classification_error, LIM:leakage, LIM:small_sample; labels have systematic issues that undermine adaptation findings; foul possessions leak into OTHER."
  },
  {
   "id": "FAM:SF-CHT-025",
   "what_failed": "Assuming play-type PPP differences are real efficiency, not labeling/foul artifacts.",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw); OTHER PPP inflated by 36% foul endings; DRIVE 12pp below foul benchmark; initiation_type maps only 0.7% of possessions."
  },
  {
   "id": "FAM:SF-CHT-029",
   "what_failed": "Detecting decaying cross-possession memory (lag-1 effect >= lag-2) for play-type actions without controlling for team quality.",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw); LIM:confounding; flat non-decaying lifts collapsed under within-team baseline, indicating team-quality confound."
  },
  {
   "id": "FAM:SF-APPS-058",
   "what_failed": "Labeling on-ball defensive coverage (DROP/ICE/SWITCH) at usable rates using NBA matchup/PBP fields.",
   "why": "A_unanswerable (question not answerable with the data or design); LIM:label_or_classification_error, LIM:small_sample; confident label rates were too low (14.9% and 3.3%) and key fields (switches_on) unpopulated."
  },
  {
   "id": "FAM:SF-APPA-030",
   "what_failed": "Verifying backfilled play-type labels match expected league distributions and team identities.",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw); LIM:label_or_classification_error; PNR and PULL_UP labels showed significant deviations from benchmarks and team identities; 2024-25 PULL_UP shares were 0.0-2.0% for many teams."
  },
  {
   "id": "FAM:SF-APPA-005",
   "what_failed": "Inferring defensive scheme changes from play-type labels.",
   "why": "A_unanswerable (question not answerable with the data or design); LIM:label_or_classification_error; inferred labels cannot separate real defensive adjustment from offense executing differently; near-uniform transition matrices consistent with label noise."
  },
  {
   "id": "FAM:SF-APPA-050",
   "what_failed": "Identifying robust superstar sequential suppression effects without multiplicity correction and with small sample sizes for specific effects.",
   "why": "E_unclear (mechanism unclear from the records); No multiplicity correction; n_after was very small (32-95) for several observed effects."
  },
  {
   "id": "FAM:SF09",
   "what_failed": "Testing for additive double-suppression stacking effects for star players.",
   "why": "LIM:implementation_bug, LIM:small_sample; results were inconclusive with stacked delta not matching additive prediction."
  }
 ],
 "evidence_establishes": [
  "There can be small, real downstream effects of specific offensive play types on the opponent's next possession PPP (e.g., CUT, TRANSITION, SPOT_UP, POST_UP showed +0.01-0.02 PPP suppression for the opponent).",
  "The derived play-type labels suffer from significant data quality issues, including systematic errors, leakage, and low confidence, leading to inflated or deflated PPP values for certain play types (e.g., SPOT_UP, TRANSITION, OTHER, DRIVE, PNR, PULL_UP). These issues can create artifacts.",
  "Apparent lag effects can be artifacts of confounding factors, specifically team quality, as demonstrated by the failure of a decay-sanity check for cross-possession memory.",
  "Inferred labels for play types and defensive schemes are prone to errors and may not reliably distinguish between actual strategic adjustments and offensive execution differences, making it difficult to interpret sequential effects as genuine strategic responses."
 ],
 "evidence_does_not_establish": [
  "Whether the *magnitude* of the identified small downstream effects (0.01-0.02 PPP) is 'large enough to drive AVOID labels' in a practical sense. The AVOID label criteria are not defined or assessed by the historical evidence.",
  "The full extent and nature of 'own-sequence lags' beyond immediate next-possession effects, or whether such lags, if real, are independent of team quality.",
  "Specific mechanisms by which play types lead to opponent next-possession PPP changes, beyond the statistical observation of a small effect.",
  "Whether the identified labeling issues have been fully resolved in the latest data versions, although the data available includes more recent seasons than some audit findings."
 ],
 "own_inferences": [
  "The research question's premise that 'opponent next-possession PPP after you run play X is large enough to drive AVOID labels' needs to define 'large enough' in the context of AVOID label thresholds, which is not provided.",
  "Given the pervasive and persistent issues with play-type label quality identified across multiple studies, any analysis relying on these labels must include rigorous validation and sensitivity checks for label accuracy.",
  "The 'own-sequence lags' part of the question is highly susceptible to confounding by team quality, as demonstrated by previous failures, and requires careful control for such factors.",
  "The observed downstream effects, while statistically real for some play types, are small in magnitude, suggesting that their direct impact on AVOID labels might be marginal unless the thresholds for AVOID are very sensitive."
 ],
 "uncertainties": [
  "The precise definition and thresholds for 'AVOID labels' are not provided, making it difficult to assess if the magnitude of effects is truly 'large enough'.",
  "The current state of play-type label accuracy in the most recent data (2025-26 season) is not explicitly confirmed to be free from the issues identified in prior audits (e.g., FAM:SF-APPM-014, FAM:SF-CHT-025, FAM:SF-APPA-030).",
  "The specific methodology for how 'own-sequence lags' will be measured and controlled for confounding factors is not detailed in the question."
 ],
 "historical_effect": {
  "changed_decision": "yes",
  "explanation": "The historical evidence significantly changed the decision from potentially proceeding directly to proceeding with substantial changes, or even not proceeding without further label validation. Specifically, FAM:SF-APPM-014, FAM:SF-CHT-025, FAM:SF-APPA-030, and FAM:SF-PAP-096 highlight severe and persistent data quality issues with play-type labels, which are foundational to the research question. This means the question, as posed, relies on data that is known to be flawed and would likely produce artifactual results. Furthermore, FAM:SF-CHT-029 directly demonstrated that apparent lag effects can be artifacts of confounding (team quality), necessitating robust controls. While FAM:SF-APPS-075 shows small real downstream effects, the label quality issues and confounding risks make a direct test unreliable without addressing these first."
 },
 "testability": {
  "p_testable": 0.2,
  "blocking_constraints": [
   {
    "code": "LABEL_ERROR",
    "text": "The foundational play-type labels are known to have significant and persistent errors, biases, and leakage, which directly impact PPP calculations and make interpretation of results unreliable (FAM:SF-APPM-014, FAM:SF-CHT-025, FAM:SF-APPA-030, FAM:SF-PAP-096)."
   },
   {
    "code": "CONFOUNDING",
    "text": "Lag effects have previously been shown to be confounded by team quality, leading to artifactual findings. Without robust controls, any observed sequential effects are likely to be spurious (FAM:SF-CHT-029)."
   },
   {
    "code": "OUTCOME_DERIVED_LABEL",
    "text": "The 'AVOID labels' are derived, and their definition is not provided. The link between small PPP changes and these labels is unclear and could be arbitrary or sensitive to thresholds."
   }
  ]
 },
 "prior_work": {
  "already_answered": "partly",
  "cited": [
   "FAM:SF-APPS-075",
   "FAM:SF-CHT-029"
  ],
  "summary": "FAM:SF-APPS-075 directly investigated 'Extended Possession Value (direct PPP + opponent T+1 suppression)' and found that 4 out of 8 play types (CUT, TRANSITION, SPOT_UP, POST_UP) had small but real downstream opponent next-PPP suppression effects (0.01-0.02 PPP). However, FAM:SF-CHT-029 found that apparent 'lag effects' for play types were artifacts of team-quality confounding, failing a decay-sanity check. The question of whether these effects are 'large enough to drive AVOID labels' and the robustness of 'own-sequence lags' against confounding remain open, especially given pervasive play-type label quality issues."
 },
 "risks": [
  {
   "code": "LABEL_ERROR",
   "text": "The play-type labels, which are central to identifying 'play X' and potentially 'own-sequence lags', have repeatedly been shown to have systematic issues, including incorrect classification, leakage, and low confidence (FAM:SF-APPM-014, FAM:SF-CHT-025, FAM:SF-APPA-030, FAM:SF-PAP-096). This could lead to misattributing effects or finding spurious correlations."
  },
  {
   "code": "CONFOUNDING",
   "text": "Any observed sequential effects (opponent next-possession PPP or own-sequence lags) are highly susceptible to confounding by factors like team quality, game state, score margin, and opponent defensive scheme. Previous attempts to identify lag effects failed due to team-quality confounding (FAM:SF-CHT-029)."
  },
  {
   "code": "OUTCOME_DERIVED_LABEL",
   "text": "The 'AVOID labels' are derived. The criteria for these labels are not specified. If they are based on arbitrary thresholds or include information that leaks from future possessions, it could create spurious findings or make the link to small PPP changes artificial."
  },
  {
   "code": "MEASURE_RELIABILITY",
   "text": "Points Per Possession (PPP) can be noisy at the play-type level, especially for less frequent play types. Small effects (like the 0.01-0.02 PPP found in FAM:SF-APPS-075) might be difficult to reliably detect and attribute without very large sample sizes and careful statistical controls."
  },
  {
   "code": "SAMPLE_SIZE_POWER",
   "text": "While overall possession counts are high, the number of instances for specific play type sequences or specific players might be insufficient to reliably detect small effects, especially when controlling for multiple confounders. Previous studies noted small N for specific effects (FAM:SF-APPA-050, FAM:SF09)."
  },
  {
   "code": "LEAKAGE_LOOKAHEAD",
   "text": "Care must be taken to ensure that the definition of 'play X' and 'own-sequence lags' does not inadvertently include information from the future that would bias the prediction of opponent next-possession PPP or AVOID labels (FAM:SF-APPM-014)."
  }
 ],
 "predicted_outcome": {
  "supported": 0.05,
  "rejected": 0.15,
  "untestable": 0.4,
  "artifact": 0.3,
  "uncertain": 0.1
 },
 "decision": "do_not_proceed",
 "design": {
  "estimand": "The causal effect of running a specific offensive play type (Play X) on the opponent's next-possession Points Per Possession (PPP), and similarly, the causal effect of own-sequence lags on opponent next-possession PPP, where 'large enough' is defined by a pre-specified threshold for AVOID labels.",
  "unit": "Possession. Each unit is an offensive possession by a team, followed by the opponent's subsequent offensive possession. For own-sequence lags, a sequence of own possessions.",
  "sample": "All NBA 2022-23, 2023-24, 2024-25, and 2025-26 (complete) regular season and playoff possessions from the provided data. Focus on play types with sufficient sample size after filtering for label quality.",
  "power": "Not estimable without first addressing label quality and confounding. If these can be addressed, power calculations would target detecting a 0.01-0.02 PPP difference (as suggested by FAM:SF-APPS-075) with 80% power at alpha=0.05, requiring very large N. The AVOID label threshold would also need to be specified to determine required effect size.",
  "controls": "Must control for strong confounders: team quality (offensive and defensive ratings of both teams), game state (score differential, time remaining, quarter), player lineups on court, opponent defensive scheme, and previous possession outcomes. A fixed-effects model (e.g., team-pair fixed effects) or regression with extensive covariates for game/team/player context will be necessary. For 'own-sequence lags', a within-team comparison (as suggested by FAM:SF-CHT-029) is critical to isolate the play-type effect from team-level characteristics.",
  "falsification": "1. Audit and validate play-type labels for the entire dataset using recent benchmarks and manual review of a subset. If label quality cannot be brought to an acceptable level (e.g., >90% confidence, <5% leakage for key play types), the study should be halted. 2. A decay-sanity check for lag effects (similar to FAM:SF-CHT-029) to ensure that observed effects are not flat across multiple lags or disappear under within-team baselines, indicating confounding. 3. Test for leakage: ensure that the 'AVOID label' definition does not incorporate information from the future.",
  "multiplicity": "Adjust for multiple comparisons if testing the effect of numerous play types or lag combinations. Bonferroni correction or FDR control should be considered.",
  "decision_rule": "The research question is not testable in its current form due to severe data quality issues with play-type labels and unaddressed confounding risks. A 'DO NOT PROCEED' decision is made until play-type label quality is demonstrably improved and a robust methodology for controlling confounding in lag effects is established and validated. If these issues are resolved, the decision rule would be based on whether the observed effect size on opponent next-possession PPP is statistically significant and exceeds the pre-defined 'large enough' threshold for AVOID labels, after controlling for confounders and validating label quality.",
  "data_version": "NBA 2022-23 to 2025-26 regular season and playoffs. Play-by-play, substitution, starters, defensive matchup, box-score data. Derived play-type possession records from the graph database, *after* a thorough re-audit and correction of play-type labels."
 }
}

